-- Sample DB2 DDL

CREATE TABLE SCHEMA1.EMPLOYEE (
    EMPNO CHAR(6) NOT NULL,
    FIRSTNME VARCHAR(12) NOT NULL,
    MIDINIT CHAR(1),
    LASTNAME VARCHAR(15) NOT NULL,
    WORKDEPT CHAR(3),
    PHONENO CHAR(4),
    HIREDATE DATE,
    JOB CHAR(8),
    EDLEVEL SMALLINT,
    SEX CHAR(1),
    BIRTHDATE DATE,
    SALARY DECIMAL(9,2),
    BONUS DECIMAL(9,2),
    COMM DECIMAL(9,2),
    PRIMARY KEY (EMPNO)
);

CREATE TABLE SCHEMA1.DEPARTMENT (
    DEPTNO CHAR(3) NOT NULL,
    DEPTNAME VARCHAR(36) NOT NULL,
    MGRNO CHAR(6),
    ADMRDEPT CHAR(3) NOT NULL,
    LOCATION CHAR(16),
    PRIMARY KEY (DEPTNO)
);

ALTER TABLE SCHEMA1.EMPLOYEE 
    ADD CONSTRAINT FK_EMP_DEPT 
    FOREIGN KEY (WORKDEPT) 
    REFERENCES SCHEMA1.DEPARTMENT (DEPTNO)
    ON DELETE SET NULL;

CREATE UNIQUE INDEX SCHEMA1.IDX_EMP_PHONE ON SCHEMA1.EMPLOYEE (PHONENO);

CREATE PROCEDURE SCHEMA1.UPDATE_SALARY (IN P_EMPNO CHAR(6), IN P_AMOUNT DECIMAL(9,2))
LANGUAGE SQL
BEGIN
    DECLARE V_CURRENT_SALARY DECIMAL(9,2);
    
    SELECT SALARY INTO V_CURRENT_SALARY 
    FROM SCHEMA1.EMPLOYEE 
    WHERE EMPNO = P_EMPNO;
    
    IF V_CURRENT_SALARY IS NOT NULL THEN
        UPDATE SCHEMA1.EMPLOYEE 
        SET SALARY = SALARY + P_AMOUNT 
        WHERE EMPNO = P_EMPNO;
    END IF;
END;
